<?php require_once __DIR__.'/../config/db.php';$pdo=db();$page=max(1,(int)($_GET['page']??1));$limit=24;$offset=($page-1)*$limit;$cat=trim($_GET['cat']??'');$q=trim($_GET['q']??'');$where=' WHERE p.is_active=1';$params=[];if($cat){$s=$pdo->prepare('SELECT id FROM categories WHERE slug=?');$s->execute([$cat]);if($id=$s->fetchColumn()){$where.=' AND p.category_id=?';$params[]=$id;}}if($q){$where.=' AND (p.name LIKE ? OR p.search_terms LIKE ? OR EXISTS(SELECT 1 FROM product_synonyms ps WHERE ps.product_id=p.id AND ps.term LIKE ?))';$like='%'.$q.'%';$params=array_merge($params,[$like,$like,$like]);}$sql='SELECT p.*,c.name category_name,c.slug category_slug FROM products p JOIN categories c ON c.id=p.category_id'.$where.' ORDER BY p.is_featured DESC,p.id DESC LIMIT '.$limit.' OFFSET '.$offset;$s=$pdo->prepare($sql);$s->execute($params);$products=$s->fetchAll();ob_start();include __DIR__.'/../includes/product_cards.php';$html=ob_get_clean();json_response(['html'=>$html,'count'=>count($products),'next'=>$page+1]);
